package org.xar.ck3.control.build;

/** Exact original GUI code is imported; only its existing software primitive fixture is supplied. */
final class GuiEightOriginalProgram {
 private GuiEightOriginalProgram() { }
 static String source() { return "import asyncio, copy, hashlib, importlib, inspect, json, pathlib, sys\nconfiguration=json.loads(pathlib.Path(sys.argv[1]).read_bytes())\ncase=json.loads(pathlib.Path(sys.argv[2]).read_bytes())\nrepo=pathlib.Path(configuration['repository_root']).resolve(strict=True); state=pathlib.Path(sys.argv[3]).resolve(strict=True)\nroot=repo/'ck3_autonomous_player'; sys.path[:0]=[str(root/'src'),str(root/'tests'/'unit'),str(root/'tests')]\ndef pinned(ref):\n    path=pathlib.Path(ref['path']).resolve(strict=True); raw=path.read_bytes()\n    assert len(raw)==ref['bytes'] and hashlib.sha256(raw).hexdigest()==ref['sha256'], str(path)\n    return raw\ndef origins():\n    observed=[]\n    for source in configuration['sources']:\n        expected=(repo/source['relative_path']).resolve(strict=True)\n        assert expected==pathlib.Path(source['original']['path']).resolve(strict=True)\n        module=importlib.import_module(source['module_name'])\n        actual=pathlib.Path(module.__file__).resolve(strict=True)\n        assert actual==expected, (source['module_name'],str(actual),str(expected))\n        pinned(source['original'])\n        observed.append({'module_name':source['module_name'],'original':source['original'],'actual_file':str(actual)})\n    return observed\nbefore_origins=origins()\nfrom xar_autoplayer.bridge import mcp_server\n_schema=None\ndef call_public(driver):\n    global _schema\n    server=mcp_server.create_server(driver)\n    tool=server._tool_manager.get_tool(case['method'])\n    assert tool is not None and tool.fn.__name__==case['method']\n    assert pathlib.Path(tool.fn.__code__.co_filename).resolve(strict=True)==(repo/'ck3_autonomous_player/src/xar_autoplayer/bridge/mcp_server.py').resolve(strict=True)\n    assert pathlib.Path(inspect.getsourcefile(mcp_server.GameplayBridgeService)).resolve(strict=True)==(repo/'ck3_autonomous_player/src/xar_autoplayer/bridge/service.py').resolve(strict=True)\n    _schema=tool.parameters\n    return asyncio.run(tool.run(arguments,None,convert_result=False))\ndef failed(error):\n    value={'accepted':False,'error':str(error),'error_kind':type(error).__name__}\n    if error.__cause__ is not None:\n        value['cause_kind']=type(error.__cause__).__name__;value['cause_message']=str(error.__cause__)\n    return value\nfrom xar_autoplayer.bridge.native_driver import NativeHeadlessGameplayDriver\ndata=json.loads(pinned(case['scenario_ref']));arguments=json.loads(pinned(case['arguments_ref']));mode=data['mode'];snapshot=data.get('snapshot')\nif mode=='arguments':\n    class ArgumentDriver:\n        def __init__(self): self.boundary_calls=0\n        def capabilities(self): return {'backend_id':'native-headless','bridge_capabilities':[],'action_steps':[]}\n        def take_snapshot(self): self.boundary_calls+=1; raise AssertionError('parameter-only fixture entered original Service observation')\n    driver=ArgumentDriver()\n    try:\n        result=call_public(driver);answer={'accepted':True,'public':result}\n    except Exception as error: answer=failed(error)\n    answer['boundary_calls']=driver.boundary_calls\nelif mode=='faith':\n    import test_faith_power_presentation_ui_v6 as fixture\n    fixture.snapshot=lambda:copy.deepcopy(snapshot)\n    options=data['options']; op=data['operation']; kind=data['kind']; subject=data['subject']\n    if kind=='clerical_interaction':\n        import test_clerical_preview_presentation_a06 as clerical\n        clerical.RECIPIENT=subject; source_context=clerical.context\n        def context(target):\n            value=source_context(target); actor=snapshot['played_character']['character_id']\n            value.update(actor_id=actor,effective_actor_id=actor,recipient_id=subject,\n                roles=[actor,subject,None,None,None,actor]); return value\n        clerical.context=context\n        raw=clerical.packet(options['presentation_target'],op,\n            'default_observed' if op=='query' else 'open_pending' if op=='open_clerical_preview' else 'close_pending')\n    elif kind=='tooltips':\n        import test_tooltip_stack_clear_a02 as stack\n        raw=stack.packet('pending' if op=='close_tooltips' else 'cleared' if options.get('presentation_receipt') else 'observed')\n    else:\n        raw=fixture.raw(kind,op,subject,target=options.get('presentation_target'),\n            index=options.get('presentation_index'),receipt=options.get('presentation_receipt'),\n            tab=options.get('presentation_tab'),absent=data.get('absent',False))\n    raw.update(native_revision=snapshot['native_revision'],date_raw=snapshot['date_raw'],\n        played_character_id=snapshot['played_character']['character_id'])\n    if op=='open_faith' and not options: raw.pop('presentation_ui')\n    # Match the actual primitive producer's backend projection (native_driver.py:13075-76).\n    raw['backend_id']='native-headless'\n    if data.get('bad_cache'):\n        raw['presentation_ui']['cache_texts']=[{'runtime_name':'tooltip','text':'observed','sha256':'0'*64}]\n    driver=fixture.Driver(raw)\n    try:\n        result=call_public(driver)\n        answer={'native':raw,'public':result,'accepted':True,'steps':[x[0] for x in driver.calls]}\n    except Exception as error:\n        answer={**failed(error),'native':raw}\nelse:\n    class Driver(NativeHeadlessGameplayDriver):\n        def __init__(self): self.after=False; self.dispatches=0; self.reads=0\n        def take_snapshot(self): return copy.deepcopy(snapshot)\n        def take_snapshot_without_native_command_history(self): return copy.deepcopy(snapshot)\n        def capabilities(self): return {'backend_id':'native-headless','bridge_capabilities':[\n            'game.command.query-white-player-business-variables-v1','game.command.query-white-rendered-text-v1',\n            'game.command.click-white-control-v1','game.command.click-white-numeric-control-v1']}\n        def _native_driver_state_path(self): return state/'driver-state.json'\n        def _record_command(self,*args,**kwargs): pass\n        def _execute_primitive_step(self,step,**kwargs):\n            if step.startswith('click-white-'):\n                self.dispatches+=1; self.after=True; value=data['ack']\n            else:\n                self.reads+=1\n                role='business' if step=='query-white-player-business-variables-v1' else 'text'\n                value=data[('after_' if self.after else 'before_')+role]\n            return {**copy.deepcopy(value),'backend_id':'native-headless'}\n    driver=Driver()\n    try:\n        result=call_public(driver)\n        answer={'accepted':True,'public':result,'dispatches':driver.dispatches,'reads':driver.reads}\n    except Exception as error:\n        answer={**failed(error),'dispatches':driver.dispatches,'reads':driver.reads}\nafter_origins=origins();assert before_origins==after_origins\nprint(json.dumps({'schema':'xar.gui-eight-original-body/v1','method':case['method'],'arguments_ref':case['arguments_ref'],\n    'scenario_ref':case['scenario_ref'],'origins':after_origins,'input_schema':_schema,'answer':answer},ensure_ascii=False,separators=(',',':')))\n"; }
}
